#!/usr/bin/env node
import { Readable, Writable } from 'node:stream';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import type { JSONRPCMessage } from '@modelcontextprotocol/sdk/types.js';
import { createGuardianMcpServer } from './mcp-server';

export const MCP_MAX_INPUT_BYTES = 65536;
const protocolErrors: Record<number, string> = {
  [-32700]: 'Parse error.', [-32600]: 'Invalid request.', [-32601]: 'Method not found.',
  [-32602]: 'Invalid parameters.', [-32603]: 'Internal error.',
};

/** Also sanitize errors generated by SDK envelope validation, before bytes reach stdout. */
export function safeProtocolMessage(message: JSONRPCMessage): JSONRPCMessage {
  if (!('error' in message)) return message;
  return {jsonrpc: '2.0', id: message.id,
    error: {code: message.error.code, message: protocolErrors[message.error.code] ?? 'MCP request failed.'}};
}

/** No CLI-wide logger, dotenv loader, provider initialization, network listener or argument-selected root. */
export async function startGuardianStdio(
  input: Readable = process.stdin, output: Writable = process.stdout, errors: Writable = process.stderr,
) {
  const server = createGuardianMcpServer();
  const transport = new StdioServerTransport(input, output, {maxBufferSize: MCP_MAX_INPUT_BYTES});
  const send = transport.send.bind(transport);
  transport.send = message => send(safeProtocolMessage(message));
  // Do not print exceptions. stdout belongs exclusively to the SDK's JSON-RPC transport.
  server.onerror = () => { errors.write('GUARDIAN_MCP_PROTOCOL_ERROR\n'); };
  const end = () => { void server.close().catch(() => { errors.write('GUARDIAN_MCP_CLOSE_FAILED\n'); }); };
  input.once('end', end);
  server.onclose = () => { input.off('end', end); input.pause(); };
  try { await server.connect(transport); }
  catch (error) { input.off('end', end); await server.close(); throw error; }
  return server;
}

if (require.main === module) {
  if (process.argv.length !== 2) {
    process.stderr.write('GUARDIAN_MCP_NO_ARGUMENTS_ALLOWED\n');
    process.exitCode = 2;
  } else {
    void startGuardianStdio().catch(() => {
      process.stderr.write('GUARDIAN_MCP_START_FAILED\n');
      process.exitCode = 1;
    });
  }
}
